// Cloudflare Worker entry: OpenNext's Next.js handler, plus a cron trigger that runs
// the hold sweep once a minute through the app's own /api/sweep route.
// @ts-expect-error .open-next/worker.js is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { SWEEP_SECRET: string; APP_URL: string };

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const req = new Request(new URL("/api/sweep", env.APP_URL), { method: "POST", headers: { "x-sweep-secret": env.SWEEP_SECRET } });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        if (!res.ok) console.error(JSON.stringify({ msg: "cron sweep failed", status: res.status }));
      }),
    );
  },
};
